import {e,icon,btn,link,Header,number,EmptyState} from './components.js';
import {formatMinor} from './daily-demo.js';
import {ensureRefinement,settlementContext,previewSettlement,monthlyHarvestModel,harvestEvents,reportStatus,reportLinks,reportEvidence,candidatesForReport,adetLabel} from './refinement-demo.js';
const fact=(title,value)=>`<div class="fact-row"><dt>${e(title)}</dt><dd>${e(value)}</dd></div>`;
const money=(value,currency='TRY')=>value==null?'Неизвестно':formatMinor(value,currency);
const gh=(s,id)=>s.daily.greenhouses.find(g=>g.id===id)?.name||'Смешанная партия';
const statusLabel={linked:'Связано',review:'На проверке',missing:'Без чека'};
const select=(name,title,options,value='',empty=null)=>`<label class="field">${e(title)}<select class="input" name="${e(name)}" data-testid="settlement-${e(name)}">${empty!=null?`<option value="">${e(empty)}</option>`:''}${options.map(([id,text])=>`<option value="${e(id)}" ${id===value?'selected':''}>${e(text)}</option>`).join('')}</select></label>`;
const input=(name,title,value='',extra='')=>`<label class="field">${e(title)}<input class="input" name="${e(name)}" data-testid="settlement-${e(name)}" value="${e(value)}" ${extra}></label>`;
export function counterpartySettlementAction(s,partyId,direction,currency='TRY') {
  let c;try{c=settlementContext(s,{partyId,direction,currency});}catch{return '';}
  return `<div class="context-actions">${btn(`${icon(direction==='receivable'?'down':'up')}${direction==='receivable'?'Записать поступление':'Записать оплату'}`,`settlement-start:${direction}:${partyId}`,'primary full','counterparty-settlement',`data-currency="${e(currency)}" ${c.availableMinor<=0?'disabled':''}`)}</div>`;
}
export function settlementValues(form) {
  const fields=new FormData(form);
  return {date:String(fields.get('date')||''),amount:String(fields.get('amount')||''),accountId:String(fields.get('accountId')||''),comment:String(fields.get('comment')||''),
    allocations:[...form.querySelectorAll('[data-allocation-id]')].filter(row=>row.querySelector('[name="allocationSelected"]').checked).map(row=>({obligationId:row.dataset.allocationId,amount:row.querySelector('[name="allocationAmount"]').value}))};
}
export function settlementForm(s,id) {
  const a=ensureRefinement(s).settlements.find(x=>x.id===id);if(!a)return EmptyState('Платёж не найден','Откройте контрагента заново.');
  if(a.status==='confirmed')return settlementReview(s,id);
  const c=settlementContext(s,a.input),i=a.input;
  return `<div class="daily-form settlement-page">${Header(i.direction==='receivable'?'Записать поступление':'Записать оплату',c.party,true)}<form id="settlement-form" data-r3-form="settlement" data-settlement-id="${e(id)}"><section class="card"><span class="tag">${i.direction==='receivable'?'Мне должны · поступление':'Я должен · выплата'} · ${e(c.currency)}</span><div class="settlement-balance"><span>Доступный остаток</span><strong>${money(c.availableMinor,c.currency)}</strong></div><p class="note">Контрагент и направление уже выбраны. Каждое обязательство распределяется явно.</p>${input('amount','Сумма платежа',i.amount,'inputmode="decimal" placeholder="0,00"')}${btn('Вся сумма · выбрать все обязательства',`settlement-fill-all:${id}`,'secondary full','settlement-fill-all','type="button"')}${select('accountId','Денежный счёт',c.accounts.map(a=>[a.id,a.name]),i.accountId,'Выберите счёт явно')}${input('date','Дата события',i.date,'type="date"')}<h2>Какие обязательства погасить?</h2><p class="note">Выбор чека не распределяет платёж автоматически. Укажите сумму напротив каждого выбранного документа.</p><div class="settlement-allocations">${c.obligations.filter(o=>o.remainingMinor>0).map(o=>{const allocation=i.allocations.find(a=>a.obligationId===o.id);return `<div class="settlement-allocation" data-allocation-id="${e(o.id)}"><label class="allocation-check"><input type="checkbox" name="allocationSelected" data-testid="settlement-select-${e(o.id)}" ${allocation?'checked':''}><span><strong>${e(o.purpose)}</strong><small>${e(o.date)} · осталось ${money(o.remainingMinor,c.currency)}</small></span></label><label class="field">Сумма для этого обязательства<input class="input" name="allocationAmount" data-testid="settlement-allocation-${e(o.id)}" inputmode="decimal" value="${e(allocation?.amount||'')}" placeholder="0,00"></label>${btn('Остаток этого документа',`settlement-fill:${id}:${o.id}`,'text-button',`settlement-fill-${o.id}`,'type="button"')}${link('Исходник',o.receiptId?`depot/${o.receiptId}`:'finance/overview','text-button')}</div>`;}).join('')}</div>${input('comment','Комментарий · необязательно',i.comment)}<p class="notice red" id="settlement-error" role="alert" hidden></p>${btn('Проверить платёж',`settlement-review:${id}`,'primary full','settlement-review','type="button"')}</section></form><p class="note">Синтетическое ДЕМО. Это погашение уже существующего долга; новый расход или продажа не создаются.</p></div>`;
}
export function settlementReview(s,id) {
  const a=ensureRefinement(s).settlements.find(x=>x.id===id);if(!a)return EmptyState('Платёж не найден','Вернитесь к контрагенту.');
  const p=previewSettlement(s,id),c=p.context,confirmed=a.status==='confirmed',source=s.daily.sources.find(x=>x.id===a.sourceId);
  return `<div class="daily-form settlement-page">${Header(confirmed?'Погашение записано':'Проверить погашение',c.party,true)}<section class="card"><span class="tag ${confirmed?'':'amber'}">${confirmed?'Подтверждено в ДЕМО':'Перед подтверждением'} · ${e(c.currency)}</span><h2 class="detail-title">${c.cashDirection==='in'?'Поступление':'Выплата'} ${money(p.amountMinor,c.currency)}</h2><dl class="fact-list">${fact('Контрагент',c.party)}${fact('Дата события',p.date)}${fact('Денежный счёт',p.account?.name||'Нужно выбрать')}${fact('Направление',c.cashDirection==='in'?'Деньги поступают · IN':'Деньги выплачиваются · OUT')}${fact('Новый остаток долга',money(p.remainingMinor,c.currency))}${p.comment?fact('Комментарий',p.comment):''}</dl><h3>Явное распределение</h3>${p.allocations.map(o=>`<div class="settlement-allocation"><strong>${e(o.purpose)}</strong><p>${money(o.beforeMinor,c.currency)} → ${money(o.afterMinor,c.currency)}</p><small>Погашение: ${money(o.amountMinor,c.currency)}</small></div>`).join('')||'<p class="note">Ни одно обязательство не выбрано.</p>'}<div class="notice">${c.cashDirection==='in'?'Один денежный приход уменьшает выбранные долги. Учтённая выручка остаётся прежней.':'Одна денежная выплата уменьшает выбранные долги. Учтённый расход остаётся прежним.'}</div>${p.date>s.daily.period.to?`<div class="notice amber">Дата позже периода обзора ${e(s.daily.period.to)}. В исторических итогах этот платёж пока не отразится.</div>`:''}${p.errors?.length&&!confirmed?`<div class="notice amber" role="alert" data-testid="settlement-clarifications"><ul>${p.errors.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`:''}${confirmed?`<div class="notice" data-testid="settlement-confirmed">Один платёж сохранён. Повторное открытие не применяет его заново.</div>${link('Открыть финансы','finance/overview','btn primary full','settlement-result-finance')}${link('На главную','home','btn secondary full','settlement-result-home')}`:`${p.canConfirm?btn('Подтвердить погашение в ДЕМО',`settlement-confirm:${id}`,'primary full','settlement-confirm',`data-revision="${p.revision}" data-ledger-revision="${p.ledgerRevision}"`):''}${link('Изменить платёж',`settlement/${id}`,'btn secondary full','settlement-edit')}`}<details class="source-details"><summary>Исходник и история проверки</summary><p>${e(source?.raw||'Источник не найден')}</p><p>Исходная запись сохранена неизменно. Уточнений: ${a.corrections.length}.</p><ol>${a.corrections.map(correction=>`<li>Версия ${correction.revision}: ${e(correction.input.date)}, сумма ${e(correction.input.amount||'не указана')}, распределений ${correction.input.allocations.length}</li>`).join('')}</ol></details></section></div>`;
}
const units={field:'веток',kg:'кг депо',revenue:'TRY'};
const metricTitle={field:'Ветки по полевым срезам',kg:'Килограммы подтверждённого депо',revenue:'Выручка подтверждённых чеков'};
const eventValue=(event,metric)=>event.value==null?'Неизвестно':metric==='revenue'?money(event.value,event.currency):`${number(event.value,metric==='kg'?3:0)} ${units[metric]}`;
function eventHistory(s,events,metric) {
  return `<div class="harvest-history">${events.map(event=>link(`<span class="history-plant">${icon(metric==='field'?'leaf':'text')}</span><span class="harvest-record-body"><strong>${e(event.date)} · ${e(gh(s,event.greenhouseId))}</strong><span>${eventValue(event,metric)}${metric==='field'?' · вес неизвестен':` · ${e(adetLabel(event.adet))}`}</span><small>${metric==='field'?e(event.fixtureLabel||'Полевой срез · источник сохранён'):event.value==null?'Вес / выручка смешанной партии по теплице не распределены':'Чек депо · собственная дата продажи'}</small></span><span class="history-status tag ${metric==='field'&&event.status!=='linked'?'amber':''}">${metric==='field'?statusLabel[event.status]:'Чек депо'}</span>${icon('arrow')}`,`${metric==='field'?'report':'depot'}/${event.id}`,'harvest-record',`harvest-event-${event.id}`)).join('')||'<p class="note empty-history">Нет записей за выбранный месяц. Это не подтверждённый нулевой урожай.</p>'}</div>`;
}
export function monthlyHarvest(s,options={}) {
  const opts={period:'season',metric:'field',month:'',sort:'newest',greenhouseId:null,...options},m=monthlyHarvestModel(s,opts),max=Math.max(...m.months.map(x=>x.value||0),1);
  const monthHeading=opts.month?new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${opts.month}-01T00:00:00Z`)):'Все месяцы';
  return `<section class="card monthly-panel" data-testid="monthly-harvest"><div class="card-header"><h2>Урожай по месяцам</h2><span class="tag amber">Синтетические данные</span></div><div class="monthly-period"><label class="field">Период<select class="input" data-harvest-option="period" data-testid="harvest-period"><option value="season" ${opts.period==='season'?'selected':''}>Сезон 2026/27</option><option value="season-2025" ${opts.period==='season-2025'?'selected':''}>Сезон 2025/26</option><option value="last12" ${opts.period==='last12'?'selected':''}>Последние 12 месяцев</option></select></label><p class="note">${e(m.period.label)} · ${e(m.period.from)} — ${e(m.period.toExclusive)} (не включая). ${opts.period==='last12'?'Текущий месяц неполный.':''}</p></div><div class="segmented monthly-metrics" role="group" aria-label="Показатель урожая">${[['field','Ветки'],['kg','Килограммы'],['revenue','Выручка']].map(([metric,title])=>btn(title,`harvest-metric:${metric}`,opts.metric===metric?'active':'',`harvest-metric-${metric}`,`aria-pressed="${opts.metric===metric}"`)).join('')}</div><p class="note">${metricTitle[opts.metric]}${opts.greenhouseId?' · '+e(gh(s,opts.greenhouseId)):''}</p><div class="monthly-bars" role="group" aria-label="Месяцы; нажмите для истории">${m.months.map(month=>{const height=month.value==null?0:Math.max(3,Math.round(month.value/max*90));return `<button class="month-button ${opts.month===month.key?'selected':''} ${month.value==null?'unknown':''}" data-action="harvest-month:${month.key}" data-testid="harvest-month-${month.key}" aria-pressed="${opts.month===month.key}" aria-label="${e(month.key)}: ${month.value==null?'нет подтверждённых записей':e(opts.metric==='revenue'?money(month.value):`${number(month.value,opts.metric==='kg'?3:0)} ${units[opts.metric]}`)}; открыть историю"><span class="month-value">${month.value==null?'—':number(opts.metric==='revenue'?month.value/100:month.value,opts.metric==='kg'?1:0)}</span><svg class="month-column" viewBox="0 0 40 100" aria-hidden="true"><rect class="month-track" x="6" y="0" width="28" height="94" rx="6"/><rect class="month-bar" x="6" y="${94-height}" width="28" height="${height}" rx="5"/></svg><span class="month-label">${e(month.label)}</span>${month.unknownCount?'<small>частично</small>':''}</button>`;}).join('')}</div><div class="monthly-total"><span>Известно за период</span><strong>${m.knownTotal==null?'Нет подтверждённых значений':opts.metric==='revenue'?money(m.knownTotal):`${number(m.knownTotal,opts.metric==='kg'?3:0)} ${units[opts.metric]}`}</strong></div><p class="coverage" data-testid="harvest-coverage">Неполное покрытие · известный вес: ${number(m.coverage.knownKg,3)} кг. Срезов без подтверждённой связи: ${m.coverage.withoutReceipt}.${m.coverage.unknownAllocation?` Смешанных чеков с неизвестным распределением: ${m.coverage.unknownAllocation}.`:''}${m.coverage.unknownCount?` Записей без значения в выбранном показателе: ${m.coverage.unknownCount}.`:''} Тире означает отсутствие подтверждённых данных, не ноль.</p></section><section class="card harvest-history-panel" data-testid="harvest-history"><div class="card-header"><h2>${opts.metric==='field'?'История срезов':'Продажи / чеки депо'}</h2>${opts.month?btn('Все месяцы','harvest-month:','text-button','harvest-month-clear'):''}</div><p class="note">${e(monthHeading)} · ${opts.metric==='field'?'Дата полевого события':'Дата подтверждённого чека; денежные поступления отдельно в финансах'}</p><div class="history-filters">${!options.lockGreenhouse?`<label class="field">Теплица<select class="input" data-harvest-option="greenhouseId" data-testid="harvest-greenhouse"><option value="">Всё хозяйство</option>${s.daily.greenhouses.map(g=>`<option value="${e(g.id)}" ${opts.greenhouseId===g.id?'selected':''}>${e(g.name)}</option>`).join('')}</select></label>`:''}<label class="field">Порядок<select class="input" data-harvest-option="sort" data-testid="harvest-sort">${[['newest','Сначала новые'],['oldest','Сначала старые'],['value','По количеству / сумме']].map(([v,l])=>`<option value="${v}" ${opts.sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${eventHistory(s,m.events,opts.metric)}${opts.metric!=='field'?`<details class="source-details"><summary>Отдельная история полевых срезов</summary>${eventHistory(s,harvestEvents(s,{...opts,metric:'field'}),'field')}</details>`:`${link('Открыть чеки депо','depots','btn secondary full','harvest-depot-records')}`}</section>`;
}
export function reportDetail(s,id) {
  ensureRefinement(s);const r=s.daily.fieldReports.find(x=>x.id===id);if(!r)return EmptyState('Срез не найден','Откройте историю урожая.');
  const source=s.daily.sources.find(x=>x.id===r.sourceId),evidence=reportEvidence(s,id),links=reportLinks(s,id),status=reportStatus(s,id);
  return `<div class="detail-layout">${Header(gh(s,r.greenhouseId),`Полевой срез · ${r.date}`,true)}<section class="card"><span class="tag ${status==='linked'?'':'amber'}" data-testid="report-status">${statusLabel[status]}</span><h2 class="detail-title">${number(r.bunches)} веток</h2><p class="note">Вес неизвестен · выручка не определяется по веткам.${r.fixtureLabel?' '+e(r.fixtureLabel):''}</p>${btn(`${icon('camera')} Сфотографировать чек депо`,`report-photo:${id}`,'primary full','report-photo')}${link('Выбрать существующий чек',`report-link/${id}`,'btn secondary full','report-existing')}<p class="note">Фото или PDF до 512 КБ останется источником в этом браузере. Автоматического распознавания нет.</p><dl class="fact-list">${fact('ID среза',r.id)}${fact('Дата события',r.date)}${fact('Теплица',gh(s,r.greenhouseId))}${fact('Ветки по полевому источнику',r.bunches)}${fact('Вес по полевому источнику','Неизвестно')}</dl></section>${evidence.length?`<section class="card"><h2>Приложенные источники</h2>${evidence.map(item=>`<article class="report-evidence" data-testid="report-evidence-${e(item.id)}"><span class="tag ${item.status==='linked'?'':'amber'}">${item.status==='linked'?'Подтверждённая связь':'На проверке'}</span>${item.file.kind==='image'?`<img class="source-image" src="${e(item.file.url)}" alt="Прикреплённое изображение чека депо">`:`<p>PDF: ${e(item.file.name||'Документ')}</p><a class="btn secondary full" href="${e(item.file.url)}" download="${e(item.file.name||'source.pdf')}" data-testid="evidence-download-${e(item.id)}">Скачать оригинал PDF</a>`}<p>${e(item.caption||'Подпись не указана')}</p>${item.replacesEvidenceId?`<p class="note">Уточнение источника ${e(item.replacesEvidenceId)}. Предыдущий оригинал сохранён ниже.</p>`:''}<p class="note">Оригинал ${e(item.sourceId)} сохранён. Приложение не создаёт продажу или платёж.</p>${link('Проверить связь с существующим чеком',`report-link/${id}/${item.id}`,'btn secondary full',`evidence-review-${item.id}`)}</article>`).join('')}</section>`:''}<section class="card"><h2>Подтверждённые связи</h2>${links.length?links.map(item=>{const receipt=s.daily.receipts.find(r=>r.id===item.receiptId);return receipt?link(`<strong>${e(receipt.id)}</strong><p>${e(receipt.date)} · ${e(adetLabel(receipt.adet))}</p>${r.bunches!==receipt.adet&&receipt.adet!=null?`<p class="notice amber">${r.bunches} ветка по срезу / ${receipt.adet} ADET по чеку — количество отличается. Связь проверена владельцем, оригиналы сохранены.</p>`:''}`,`depot/${receipt.id}`,'daily-record',`linked-${id}-${receipt.id}`):'';}).join(''):'<p class="note">Пока нет. Совпадение даты — не доказательство связи.</p>'}<p class="note">Один чек может относиться к нескольким срезам. Связь не распределяет вес или выручку по теплицам.</p></section><section class="card source-evidence"><span class="eyebrow">ОРИГИНАЛ ПОЛЕВОГО ИСТОЧНИКА</span><p data-testid="report-original">${e(source?.raw||'Исходный текст не сохранён')}</p><p class="note">${e(source?.capturedAt||'Время захвата неизвестно')}</p></section></div>`;
}
export function receiptLinkForm(s,reportId,evidenceId=null) {
  const r=s.daily.fieldReports.find(r=>r.id===reportId);if(!r)return EmptyState('Срез не найден','Вернитесь к истории.');
  return `${Header('Выбрать чек депо',`${gh(s,r.greenhouseId)} · ${r.date} · ${r.bunches} веток`,true)}<div class="notice">Сначала ближайшие даты. Дата — предложение, не доказательство связи. Фото, срез и продажа сохраняются отдельно.</div>${evidenceId?'<p class="note">Проверяется связь выбранного приложенного источника и чека.</p>':''}<div class="daily-list">${candidatesForReport(s,reportId).map(c=>`<section class="card receipt-candidate" data-testid="receipt-candidate-${e(c.receiptId)}"><div class="card-header"><h2>${e(c.party)}</h2><span class="tag ${c.alreadyLinked?'':'amber'}">${c.alreadyLinked?'Уже связан':c.sameDate?'Та же дата · кандидат':'Кандидат'}</span></div><strong>${e(c.date)} · ${e(c.adetLabel)}</strong><p>${number(c.netKg,3)} кг · ${money(c.totalMinor,c.currency)}</p>${c.mismatch?`<div class="notice amber" data-testid="receipt-count-mismatch">Количество отличается — проверить связь: ${r.bunches} ветка по полю / ${c.adet} ADET по чеку.</div>`:''}${c.otherReportCount?`<p class="note">Уже связан с другими срезами: ${c.otherReportCount}. Это не исключает текущий срез, но требует явной проверки.</p>`:''}${link('Открыть исходник чека',`depot/${c.receiptId}`,'btn secondary full')}${!c.alreadyLinked||evidenceId?btn('Проверить эту связь',`receipt-link-start:${reportId}:${c.receiptId}${evidenceId?':'+evidenceId:''}`,'primary full',`receipt-select-${c.receiptId}`):''}</section>`).join('')}</div>`;
}
export function receiptLinkReview(s,id) {
  const a=ensureRefinement(s).linkReviews.find(x=>x.id===id);if(!a)return EmptyState('Проверка не найдена','Выберите срез и чек.');
  const r=s.daily.fieldReports.find(r=>r.id===a.reportId),receipt=s.daily.receipts.find(r=>r.id===a.receiptId),confirmed=a.status==='confirmed';
  return `<div class="daily-form">${Header('Проверить связь','Срез и чек остаются разными источниками',true)}<section class="card"><dl class="fact-list">${fact('Полевой срез',`${r.date} · ${gh(s,r.greenhouseId)}`)}${fact('Ветки по полю',`${r.bunches} веток`)}${fact('Чек депо',`${receipt.date} · ${receipt.id}`)}${fact('Ветки по чеку',adetLabel(receipt.adet))}</dl>${receipt.adet!=null&&r.bunches!==receipt.adet?`<div class="notice amber" data-testid="receipt-count-mismatch">Количество отличается — проверить связь: ${r.bunches} ветка / ${receipt.adet} ADET. Значения не исправляются автоматически.</div>`:''}<div class="notice">Подтверждается только связь источников. Килограммы, выручка, денежный платёж и распределение по теплицам не создаются.</div>${confirmed?`<div class="notice" data-testid="receipt-link-confirmed">Связь подтверждена в ДЕМО.</div>${link('Вернуться к срезу',`report/${r.id}`,'btn primary full','receipt-link-result')}`:`<label class="allocation-check"><input type="checkbox" id="receipt-link-reviewed" data-testid="receipt-link-reviewed"><span>Проверил, что этот чек относится к выбранному срезу, включая различия количества</span></label>${btn('Подтвердить только связь',`receipt-link-confirm:${id}`,'primary full','receipt-link-confirm',`data-revision="${a.revision}"`)}`}</section></div>`;
}
